import {submissionBundle} from './submission-bundle.mjs';
const decode=bytes=>new TextDecoder('utf-8',{fatal:true}).decode(bytes);
export function inspectSubmissionBundle(data,inspect){
 try{let pos=0;const entries=[];while(pos+4<=data.length&&data.readUInt32LE(pos)===0x04034b50){if(entries.length>=21||pos+30>data.length)throw Error();const flags=data.readUInt16LE(pos+6),method=data.readUInt16LE(pos+8),compressed=data.readUInt32LE(pos+18),size=data.readUInt32LE(pos+22),nameLength=data.readUInt16LE(pos+26),extraLength=data.readUInt16LE(pos+28);if(flags!==0x800||method!==0||compressed!==size||!nameLength||extraLength||pos+30+nameLength+size>data.length)throw Error();const name=decode(data.subarray(pos+30,pos+30+nameLength)),start=pos+30+nameLength;entries.push({name,data:data.subarray(start,start+size)});pos=start+size}if(entries.length<3||entries[0].name!=='manifest.json'||entries[0].data.length>50000)throw Error();const manifest=JSON.parse(decode(entries[0].data));if(!manifest||manifest.version!==1||!Array.isArray(manifest.files)||manifest.files.length!==entries.length-1)throw Error();const files=manifest.files.map((f,i)=>{const entry=entries[i+1];if(!f||typeof f.name!=='string'||entry.name!=='files/'+f.name)throw Error();return {record:{id:f.id,exam:manifest.exam,student:manifest.student,taskId:manifest.taskId,path:f.name,size:f.size,sha256:f.sha256},data:entry.data}});if(!submissionBundle(files).equals(data))throw Error();return {status:'ok',kind:'bundle',files:files.map(({record,data})=>({name:record.path,inspection:record.path.toLowerCase().endsWith('.zip')?{status:'unsupported',kind:'zip'}:inspect(record.path,data)}))};
 }catch{return {status:'invalid',kind:'bundle'}}
}
